(()=>{
const menu=document.getElementById('menu-toggle');function closeMenu(){menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Abrir menu')};menu?.addEventListener('click',()=>{const on=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(on));menu.setAttribute('aria-label',on?'Fechar menu':'Abrir menu')});document.querySelectorAll('#main-nav a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus()}});document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu()});
const dialog=document.getElementById('chapter-dialog');let returnFocus;
function openStory(key){const s=YUGEN_STORIES[key];if(!s)return;returnFocus=document.activeElement;document.getElementById('chapter-dialog-label').textContent=s.label;document.getElementById('chapter-dialog-glyph').textContent=s.kanji;document.getElementById('chapter-dialog-title').textContent=s.title;const body=document.getElementById('chapter-dialog-body');body.replaceChildren(...s.paragraphs.map(t=>{const p=document.createElement('p');p.textContent=t;return p}));const note=document.createElement('p');note.className='detail';note.textContent=s.detail;body.append(note);document.body.classList.add('dialog-open');dialog.showModal();dialog.scrollTop=0;let stamps=[];try{const saved=JSON.parse(localStorage.getItem('yugen-stamps')||'[]');if(Array.isArray(saved))stamps=saved;if(!stamps.includes('pop')){stamps.push('pop');localStorage.setItem('yugen-stamps',JSON.stringify(stamps))}}catch{}}
function closeDialog(){dialog.close()}dialog?.querySelectorAll('.close-dialog,[data-close-dialog]').forEach(b=>b.addEventListener('click',closeDialog));dialog?.addEventListener('close',()=>{document.body.classList.remove('dialog-open');returnFocus?.focus()});dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
const moodPairs={adventure:['onepiece','fullmetal'],wonder:['spirited','totoro'],life:['silent','march']};function setMood(mood){const target=document.getElementById('mood-results');if(!target)return;document.querySelectorAll('[data-mood]').forEach(b=>{b.classList.toggle('active',b.dataset.mood===mood);b.setAttribute('aria-pressed',String(b.dataset.mood===mood))});target.replaceChildren(...moodPairs[mood].map(key=>{const s=YUGEN_STORIES[key];const button=document.createElement('button');button.className='mood-result';button.dataset.symbol=s.kanji;const label=document.createElement('p');label.className='eyebrow';label.textContent=s.label;const h=document.createElement('h3');h.textContent=s.title;const description=document.createElement('p');description.textContent=s.paragraphs[0];const call=document.createElement('span');call.textContent='Abra esta história ↗';button.append(label,h,description,call);button.addEventListener('click',()=>openStory(key));return button}))}document.querySelectorAll('[data-mood]').forEach(b=>b.addEventListener('click',()=>setMood(b.dataset.mood)));setMood('adventure');
document.querySelectorAll('[data-pace]').forEach(b=>b.addEventListener('click',()=>{const fast=b.dataset.pace==='fast';document.getElementById('comic-strip').classList.toggle('fast',fast);document.querySelectorAll('[data-pace]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.getElementById('pace-note').textContent=fast?'Quadros próximos, ângulos e contraste sugerem urgência. O mesmo instante ganha outro impulso.':'Espaços mais largos deixam cada instante respirar. Leia devagar.'}));
document.getElementById('repair-bowl')?.addEventListener('click',e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));document.querySelector('.kintsugi-demo').classList.toggle('repaired',on);e.currentTarget.innerHTML=on?'Veja a peça novamente <span>↺</span>':'Ilumine as marcas <span>✳</span>';document.getElementById('repair-caption').textContent=on?'O que foi reparado também faz parte da beleza.':'A história já está na peça.'});
if('IntersectionObserver' in window){const chapters=document.querySelectorAll('.ritual-chapter');const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){const glyph=document.getElementById('ritual-totem-symbol');if(glyph)glyph.textContent=entry.target.dataset.symbol;document.querySelectorAll('.chapter-subnav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id))}})},{rootMargin:'-15% 0px -45% 0px'});chapters.forEach(a=>observer.observe(a))}
const stations={tokyo:{glyph:'東',label:'BILHETE 01 / TÓQUIO',title:'Mais de uma cidade<br>na mesma cidade.',description:'O brilho das telas convive com pequenas lojas, tradições e encontros de bairro. Tóquio pode mudar de atmosfera a cada esquina: vale olhar além da imagem mais conhecida.',prompt:'Observe os contrastes de escala: um grande edifício, uma passagem estreita e uma pequena fachada podem contar histórias diferentes.',url:'https://www.gotokyo.org/en/see-and-do/culture/index.html',art:'FOTO REAL / BASILE MORIN / SHINJUKU, 2019'},kyoto:{glyph:'京',label:'BILHETE 02 / KYOTO',title:'O presente também<br>guarda memórias.',description:'A cultura do chá se conecta a ofícios como a cerâmica, a laca e o trabalho com bambu. Em Kyoto, observar um utensílio pode ser uma forma de encontrar o trabalho de muitas pessoas.',prompt:'Repare nos materiais e nos objetos do cotidiano. Que mãos, técnicas e escolhas existem por trás de cada detalhe?',url:'https://kyoto.travel/en/art-and-culture/',art:'FOTO REAL / JOSEP M. GRACIA / KYOTO, 2015'},osaka:{glyph:'食',label:'BILHETE 03 / OSAKA',title:'Uma cidade que<br>também se saboreia.',description:'A comida, a diversão e a vida noturna estão entre os caminhos para conhecer Osaka. A cultura gastronômica oferece outro jeito de olhar a cidade: pelas mesas, pelos encontros e pela curiosidade.',prompt:'Além do prato, observe o ambiente: a conversa, o preparo e a maneira como as pessoas compartilham o espaço também fazem parte da experiência.',url:'https://www.japan.travel/en/destinations/kansai/osaka/',art:'FOTO REAL / MARTIN FALBISONER / OSAKA, 2016'}};
function setStation(key){const s=stations[key];if(!document.getElementById('station-content'))return;document.querySelectorAll('[data-station]').forEach(b=>{const on=b.dataset.station===key;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});document.getElementById('station-content').setAttribute('aria-labelledby',key+'-station');document.getElementById('station-visual').className='station-visual '+key;document.getElementById('station-title').innerHTML=s.title;['glyph','label','description','prompt'].forEach(p=>document.getElementById('station-'+p).textContent=s[p]);document.getElementById('station-art-note').textContent=s.art;document.getElementById('station-source').href=s.url}setStation('tokyo');const stationTabs=[...document.querySelectorAll('[data-station]')];stationTabs.forEach((b,i)=>{b.addEventListener('click',()=>setStation(b.dataset.station));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;stationTabs[n].focus();setStation(stationTabs[n].dataset.station)}})});
})();
